package dev.redstoneengineering.block;
import com.mojang.serialization.MapCodec;import dev.redstoneengineering.RedstoneEngineering;import dev.redstoneengineering.physics.PneumaticNetwork;import net.minecraft.core.*;import net.minecraft.network.chat.Component;import net.minecraft.server.level.ServerLevel;import net.minecraft.world.*;import net.minecraft.world.entity.player.Player;import net.minecraft.world.level.*;import net.minecraft.world.level.block.Block;import net.minecraft.world.level.block.state.*;import net.minecraft.world.level.block.state.properties.BooleanProperty;import net.minecraft.world.phys.BlockHitResult;
/** Manual inline isolation valve. Closed state blocks pneumatic propagation without deleting stored pressure. */
public class PneumaticValveBlock extends DirectionalDomainBlock{public static final BooleanProperty OPEN=BooleanProperty.create("open");public PneumaticValveBlock(Properties p){super(p);registerDefaultState(defaultBlockState().setValue(OPEN,true));}@Override public MapCodec<PneumaticValveBlock> codec(){return RedstoneEngineering.PNEUMATIC_VALVE_CODEC.value();}@Override protected void createBlockStateDefinition(StateDefinition.Builder<Block,BlockState>b){super.createBlockStateDefinition(b);b.add(OPEN);}@Override protected InteractionResult useWithoutItem(BlockState s,Level l,BlockPos p,Player pl,BlockHitResult h){if(!l.isClientSide){boolean n=!s.getValue(OPEN);BlockState ns=s.setValue(OPEN,n);l.setBlock(p,ns,Block.UPDATE_CLIENTS);if(l instanceof ServerLevel sl)PneumaticNetwork.recompute(sl,p);pl.displayClientMessage(Component.literal("Pneumatic valve "+(n?"OPEN":"CLOSED")),true);}return InteractionResult.sidedSuccess(l.isClientSide);}}
